#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

REPO="erikgunawans/ent-os-new-jup"   # where the secret is stored
JUP="erikgunawans/jup"               # what the token must be able to read

banner "JUP_REPO_TOKEN — the last credential for the drift gates (#13)"

# ── 1. Mint the token ─────────────────────────────────────────────────────
stage "Mint a fine-grained PAT"
say "The drift gates check the live JUP tree against what is deployed. To do"
say "that they must read $JUP, which is private. This token is how."
say ""
note "Read-only. It can never write to either repository."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: drift-gates (ent-os-new-jup)"
step "Resource owner: erikgunawans"
step "Expiration: pick a date — and put the renewal in your calendar now."
step "Repository access: 'Only select repositories' → select 'jup'"
step "Permissions → Repository permissions → Contents → Read-only"
note "Metadata: Read-only is added automatically and is mandatory. Leave it."
step "Generate token, then copy the github_pat_... value."
warn "Copy the WHOLE value. A truncated paste fails as 'Bad credentials',"
warn "which reads like a permissions problem and is not one."
ask_secret JUP_REPO_TOKEN "Paste the token:"

# ── 2. Verify BEFORE storing ──────────────────────────────────────────────
# This stage exists because the first attempt at this credential failed in CI
# with 'Bad credentials' — the token was stored without ever being tried, so
# the first thing that exercised it was a nightly gate. Prove it here instead.
stage "Verify the token actually works"

if [[ -z "${JUP_REPO_TOKEN:-}" ]]; then
  warn "No token entered. Re-run when you have one."
  exit 1
fi

# Whitespace is the single likeliest defect, and it is invisible in a terminal.
if [[ "$JUP_REPO_TOKEN" =~ [[:space:]] ]]; then
  warn "The value contains whitespace or a newline."
  warn "That alone produces 'Bad credentials'. Copy it again, without the"
  warn "trailing newline, and re-run."
  exit 1
fi
say "No stray whitespace."

_api() { # _api PATH -> prints HTTP status
  curl -sS -o /dev/null -w '%{http_code}' \
    -H "Authorization: Bearer $JUP_REPO_TOKEN" \
    -H "Accept: application/vnd.github+json" \
    "https://api.github.com/$1" 2>/dev/null || echo "000"
}

# Three checks, narrowing from 'is the token real' to 'can it do the one job'.
code=$(_api "user")
if [[ "$code" != "200" ]]; then
  warn "GitHub rejected the token itself (HTTP $code)."
  note "401 means the string is wrong — truncated, expired, or revoked."
  note "It does NOT mean the permissions are wrong; that shows up next."
  exit 1
fi
say "The token is valid."

code=$(_api "repos/$JUP")
if [[ "$code" != "200" ]]; then
  warn "The token is valid but cannot see $JUP (HTTP $code)."
  note "404 here means repository access was not granted. Re-run and pick"
  note "'Only select repositories' → jup."
  exit 1
fi
say "It can see $JUP."

# The checkout needs Contents specifically; metadata alone would pass above.
code=$(_api "repos/$JUP/contents/records")
if [[ "$code" != "200" ]]; then
  warn "The token can see the repo but not its Contents (HTTP $code)."
  note "Re-run and set Repository permissions → Contents → Read-only."
  exit 1
fi
say "It can read Contents — which is exactly what actions/checkout needs."

# Read-only was the promise; verify it rather than trusting the checkbox.
#
# The probe writes the repository's CURRENT description back to itself. If the
# token turns out to be over-scoped the PATCH succeeds and changes nothing —
# a probe that damaged the repo to prove it could would be a bad trade.
current_desc=$(curl -sS \
  -H "Authorization: Bearer $JUP_REPO_TOKEN" \
  -H "Accept: application/vnd.github+json" \
  "https://api.github.com/repos/$JUP" 2>/dev/null \
  | python3 -c 'import json,sys; print(json.dumps(json.load(sys.stdin).get("description") or ""))' 2>/dev/null || echo '""')

code=$(curl -sS -o /dev/null -w '%{http_code}' -X PATCH \
  -H "Authorization: Bearer $JUP_REPO_TOKEN" \
  -H "Accept: application/vnd.github+json" \
  -d "{\"description\":$current_desc}" \
  "https://api.github.com/repos/$JUP" 2>/dev/null || echo "000")

if [[ "$code" == "200" ]]; then
  warn "This token can WRITE to $JUP. It was meant to be read-only."
  warn "Nothing was changed — the probe wrote the existing description back."
  warn "Re-mint it with Contents: Read-only and no other permission."
  confirm "Store it anyway?" || exit 1
else
  say "It cannot write (HTTP $code) — read-only confirmed."
fi

# ── 3. Store it ───────────────────────────────────────────────────────────
stage "Store it as a repository secret"
say "Target: $REPO"
note "set_secret pipes with printf '%s', so no trailing newline is stored."
note "It is deliberately NOT written to .env: this is a CI-only credential,"
note "and a second copy on disk is the problem ticket #11 is about."
if [[ "$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null)" != "$REPO" ]]; then
  warn "Run this from the $REPO checkout; gh targets the current repo."
  exit 1
fi
set_secret JUP_REPO_TOKEN "$JUP_REPO_TOKEN"

# ── 4. Prove the gates run ────────────────────────────────────────────────
stage "Prove the gates actually run"
say "All three credentials are in place, so all four jobs should now run."
if confirm "Dispatch 'Drift gates' now and watch it?"; then
  gh workflow run "Drift gates" --repo "$REPO" >/dev/null 2>&1 || warn "dispatch failed"
  say "Dispatched. Waiting for it to finish..."
  sleep 10
  run_id=$(gh run list --repo "$REPO" --workflow "Drift gates" --limit 1 \
    --json databaseId --jq '.[0].databaseId' 2>/dev/null || echo "")
  if [[ -n "$run_id" ]]; then
    until [[ "$(gh run view "$run_id" --repo "$REPO" --json status --jq .status 2>/dev/null)" == "completed" ]]; do
      sleep 10
    done
    printf '\n'
    gh run view "$run_id" --repo "$REPO" 2>&1 | sed -n '1,12p' | sed 's/^/  /'
    printf '\n'
    note "Four green jobs means the gate is live and runs nightly from now on."
    note "A red kb-drift or record-sync means real drift, not a broken token —"
    note "the token was proven in stage 2."
  fi
else
  SKIPPED+=("verify the gates: gh workflow run \"Drift gates\" --repo $REPO")
fi

finish
